const {exec} = require('child_process');

// Function to run Lighthouse and capture the user agent
function runLighthouse(url) {
  exec(`lighthouse ${url} --output=json`, (error, stdout, stderr) => {
    if (error) {
      console.error(`exec error: ${error}`);
      return;
    }
    const report = JSON.parse(stdout);
    console.log('Lighthouse User Agent:', report.userAgent);
  });
}

// Function to simulate a request to the server and log the user agent
function simulateRequest(url) {
  const http = require('http');

  const options = {
    hostname: 'tolwin.spdns.org',
    port: 80,
    path: '/index.html',
    method: 'GET',
    headers: {
      'User-Agent': 'Mozilla/5.0 (Linux; Android 6.0.1; Nexus 5 Build/MRA58N) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/66.0.3359.139 Mobile Safari/537.36'
    }
  };

  const req = http.request(options, (res) => {
    console.log(`STATUS: ${res.statusCode}`);
    console.log(`HEADERS: ${JSON.stringify(res.headers)}`);
  });

  req.on('error', (e) => {
    console.error(`problem with request: ${e.message}`);
  });

  req.end();
}

// Run both functions to reproduce the issue
runLighthouse('https://tolwin.spdns.org/index.html');
simulateRequest('https://tolwin.spdns.org/index.html');
